(* [comment removed for export] *)
Lemma run_apart : forall l lo n (a nZ : Z),
  covered l lo n -> 0 < nZ -> 0 < n ->
  (forall p, In p l -> a + nZ <= fst p \/ fst p + snd p <= a) ->
